// Generated by build.py. The cache name is derived from the page contents, so
// publishing a new build invalidates the old one instead of serving it forever.
const CACHE = "bible-clue-001246ed";
const ASSETS = [
  "./", "./index.html", "./manifest.webmanifest",
  "./icon-180.png", "./icon-192.png", "./icon-512.png",
];

self.addEventListener("install", event => {
  event.waitUntil(caches.open(CACHE).then(c => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

// Cache first, so the installed app opens instantly and works with no network at
// all -- the moderator may be on a bad connection in the middle of a meeting.
// A fresh copy is fetched in the background; because publishing a new build
// changes this file's bytes, the browser installs the new cache and the update
// lands on the next launch.
self.addEventListener("fetch", event => {
  if (event.request.method !== "GET") return;
  event.respondWith(
    caches.match(event.request).then(hit => {
      const network = fetch(event.request)
        .then(response => {
          if (response && response.ok) {
            const copy = response.clone();
            caches.open(CACHE).then(c => c.put(event.request, copy));
          }
          return response;
        })
        .catch(() => hit || caches.match("./index.html"));
      return hit || network;
    })
  );
});
